  "times.py": "from datetime import datetime, timezone


def instant(value):
    if isinstance(value, datetime):
        parsed = value
    elif isinstance(value, str):
        try:
            parsed = datetime.fromisoformat(value)
        except Exception:
            raise ValueError('invalid ISO8601 datetime') from None
    else:
        raise ValueError('value must be an ISO8601 string or datetime')

    try:
        offset = parsed.utcoffset()
    except Exception:
        raise ValueError('invalid datetime offset') from None
    if offset is None:
        raise ValueError('datetime must be timezone-aware')

    try:
        return parsed.astimezone(timezone.utc)
    except Exception:
        raise ValueError('datetime cannot be normalized to UTC') from None
