  "quotes.py": "import math
import times


def probability(value):
    if isinstance(value, bool) or not isinstance(value, (int, float, str)):
        raise ValueError('odds must be an int, float, or string')

    try:
        odds = float(value)
    except Exception:
        raise ValueError('odds are not convertible to float') from None

    if not math.isfinite(odds):
        raise ValueError('odds must be finite')
    if abs(odds) < 100.0:
        raise ValueError('odds must have magnitude at least 100')

    if odds > 0.0:
        return 100.0 / (odds + 100.0)

    magnitude = -odds
    return magnitude / (magnitude + 100.0)


def select(rows, event, asof):
    cutoff = times.instant(asof)
    if not isinstance(event, str) or len(event) == 0:
        raise ValueError('event must be a nonempty string')

    winners = {}

    for row in rows:
        if not isinstance(row, dict):
            continue

        try:
            quote_id = dict.get(row, 'id')
            book = dict.get(row, 'book')
            quote_event = dict.get(row, 'event')

            if (
                not isinstance(quote_id, str)
                or len(quote_id) == 0
                or not isinstance(book, str)
                or len(book) == 0
                or not isinstance(quote_event, str)
                or len(quote_event) == 0
            ):
                continue

            if quote_event != event:
                continue

            observed = times.instant(dict.get(row, 'observed_at'))
            expires = times.instant(dict.get(row, 'expires_at'))
            last_update = times.instant(dict.get(row, 'last_update'))

            if observed > cutoff:
                continue
            if cutoff >= expires:
                continue
            if last_update > observed:
                continue

            quote_probability = probability(dict.get(row, 'odds'))
            current = winners.get(book)

            if (
                current is None
                or observed > current[0]
                or (observed == current[0] and quote_id < current[1])
            ):
                winners[book] = (
                    observed,
                    quote_id,
                    row,
                    quote_probability,
                )
        except Exception:
            continue

    return {
        book: {'row': entry[2], 'probability': entry[3]}
        for book, entry in winners.items()
    }
