  "runs.py": "import times


def reconcile(rows, asof):
    cutoff = times.instant(asof)
    by_run_id = {}

    for row in rows:
        if not isinstance(row, dict):
            continue

        try:
            run_id = dict.get(row, 'run_id')
            job = dict.get(row, 'job')
            attempt = dict.get(row, 'attempt')
            status = dict.get(row, 'status')
            downloaded_rows = dict.get(row, 'downloaded_rows')

            if (
                not isinstance(run_id, str)
                or len(run_id) == 0
                or not isinstance(job, str)
                or len(job) == 0
            ):
                continue

            if isinstance(attempt, bool) or not isinstance(attempt, int):
                continue
            attempt_value = int(attempt)
            if attempt_value <= 0:
                continue

            if (
                isinstance(downloaded_rows, bool)
                or not isinstance(downloaded_rows, int)
            ):
                continue
            downloaded_value = int(downloaded_rows)
            if downloaded_value < 0:
                continue

            if (
                not isinstance(status, str)
                or status not in ('ok', 'partial', 'failed', 'pending')
            ):
                continue
            if status in ('failed', 'pending') and downloaded_value != 0:
                continue

            observed = times.instant(dict.get(row, 'observed_at'))
            if observed > cutoff:
                continue

            current = by_run_id.get(run_id)
            if current is None or observed > current[0]:
                by_run_id[run_id] = (
                    observed,
                    attempt_value,
                    job,
                    downloaded_value,
                    row,
                )
        except Exception:
            continue

    selected = {}

    for run_id, entry in by_run_id.items():
        try:
            observed, attempt_value, job, _downloaded_value, row = entry
            current = selected.get(job)

            if (
                current is None
                or attempt_value > current[0]
                or (
                    attempt_value == current[0]
                    and observed > current[1]
                )
                or (
                    attempt_value == current[0]
                    and observed == current[1]
                    and run_id < current[2]
                )
            ):
                selected[job] = (
                    attempt_value,
                    observed,
                    run_id,
                    row,
                )
        except Exception:
            continue

    return {job: entry[3] for job, entry in selected.items()}
