  "pipeline.py": "import times
import quotes
import runs


def snapshot(quote_rows, run_rows, event, asof):
    normalized_asof = times.instant(asof)
    if not isinstance(event, str) or len(event) == 0:
        raise ValueError('event must be a nonempty string')

    selected_quotes = quotes.select(quote_rows, event, normalized_asof)
    selected_runs = runs.reconcile(run_rows, normalized_asof)

    successful_rows = 0
    failures = []
    partial_jobs = []
    unknown_jobs = []

    for job, row in selected_runs.items():
        status = dict.get(row, 'status')

        if status == 'ok' or status == 'partial':
            successful_rows += int(dict.get(row, 'downloaded_rows'))
        elif status == 'failed':
            failures.append(job)
        elif status == 'pending':
            unknown_jobs.append(job)

    failures.sort()
    partial_jobs.sort()
    unknown_jobs.sort()

    return {
        'quotes': selected_quotes,
        'runs': selected_runs,
        'successful_rows': successful_rows,
        'failures': failures,
        'partial_jobs': partial_jobs,
        'unknown_jobs': unknown_jobs,
    }
